package web

import (
	"math"
	"os"
	"path/filepath"
	"testing"

	"github.com/CC-RMD-EpiBio/gofluttercat/backend-golang/pkg/biascorrection"
	"github.com/CC-RMD-EpiBio/gofluttercat/backend-golang/pkg/irtcat"
	"github.com/mederrata/ndvek"
)

// condFixturePath points at the shared synthetic conditional-BCM fixture
// (8 items, item_00..item_07) generated by the biascorrection testdata script.
func condFixturePath() string {
	return filepath.Join("..", "biascorrection", "testdata", "bcm_conditional_fixture.json")
}

// TestLoadConditionalBCMs covers the deployment loader: finding and loading a
// saved conditional BCM from a configured BcmDir under both supported layouts.
func TestLoadConditionalBCMs(t *testing.T) {
	src, err := os.ReadFile(condFixturePath())
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	// loadConditionalBCMs only iterates the scale keys; the model value is never
	// dereferenced, so a zero-value model is fine here.
	models := map[string]*irtcat.GradedResponseModel{"synthetic_cond": {}}

	// Flat layout: <dir>/bcm_<scale>_conditional.json
	flat := t.TempDir()
	if err := os.WriteFile(filepath.Join(flat, "bcm_synthetic_cond_conditional.json"), src, 0o644); err != nil {
		t.Fatal(err)
	}
	got := loadConditionalBCMs("test", flat, models)
	if got == nil || got["synthetic_cond"] == nil {
		t.Fatalf("flat layout: BCM not loaded")
	}
	if n := len(got["synthetic_cond"].ItemKeys); n != 8 {
		t.Errorf("ItemKeys = %d, want 8", n)
	}

	// Nested layout: <dir>/<scale>/bcm_<scale>_conditional.json
	nested := t.TempDir()
	dir := filepath.Join(nested, "synthetic_cond")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "bcm_synthetic_cond_conditional.json"), src, 0o644); err != nil {
		t.Fatal(err)
	}
	if got := loadConditionalBCMs("test", nested, models); got == nil || got["synthetic_cond"] == nil {
		t.Fatalf("nested layout: BCM not loaded")
	}

	// No dir configured -> nil (unchanged behavior).
	if got := loadConditionalBCMs("test", "", models); got != nil {
		t.Errorf("empty bcmDir: got %v, want nil", got)
	}
	// Missing file -> scale omitted -> nil map.
	if got := loadConditionalBCMs("test", t.TempDir(), models); got != nil {
		t.Errorf("missing file: got %v, want nil", got)
	}
}

// TestScorerAppliesBCM proves the administration path: a scorer carrying a
// conditional BCM returns the bias-corrected EAP and a widened SD, exactly the
// quantities the summary handler now reports.
func TestScorerAppliesBCM(t *testing.T) {
	bcm, err := biascorrection.LoadBCMConditional(condFixturePath())
	if err != nil {
		t.Fatal(err)
	}

	grid := ndvek.Linspace(-4, 4, 81)
	energy := make([]float64, len(grid))
	for i, x := range grid {
		energy[i] = -0.5 * x * x // standard-normal posterior
	}
	bs := &irtcat.BayesianScore{Energy: energy, Grid: grid}
	raw := bs.ObservedOnlyMean()

	// Administer the first half of the battery.
	administered := map[string]bool{}
	var answered []*irtcat.Response
	for i, k := range bcm.ItemKeys {
		if i < len(bcm.ItemKeys)/2 {
			answered = append(answered, &irtcat.Response{Item: &irtcat.Item{Name: k}, Value: 1})
			administered[k] = true
		}
	}
	scorer := &irtcat.BayesianScorer{Bcm: bcm, Answered: answered, Running: bs}

	// AdjustedMean applies exactly the BCM's ApplyByKey correction.
	gotMean := bs.AdjustedMean(scorer)
	wantMean := bcm.ApplyByKey(raw, administered)
	if math.Abs(gotMean-wantMean) > 1e-9 {
		t.Errorf("AdjustedMean = %v, want ApplyByKey = %v", gotMean, wantMean)
	}

	// A scorer without a BCM falls back to the observed-only mean.
	if got := bs.AdjustedMean(&irtcat.BayesianScorer{Running: bs}); math.Abs(got-raw) > 1e-12 {
		t.Errorf("no-BCM AdjustedMean = %v, want raw = %v", got, raw)
	}

	// AdjustedStd widens (or equals) the observed-only SD: sqrt(err^2 + bias^2).
	if as, es := bs.AdjustedStd(scorer), bs.ObservedOnlyStd(); as < es-1e-12 {
		t.Errorf("AdjustedStd = %v < ObservedOnlyStd = %v", as, es)
	}
}
